  /* ——— Jewellery (2026-10-09). Reviews stay off (category rule). FirstClub's 10-day return is the only
     return info: the brand's own "Returns" rows are removed. Rails: Complete your look + See similar only
     (Bought together folds into Complete your look; More from the brand is usually one item). ——— */
  const JCHECKS = {
    "Plating coverage": ["Finish checked for even coverage, with no bare patches or bubbling.", "format_paint"],
    "Stones & settings": ["Settings checked so no stone or charm sits loose.", "diamond"],
    "Clasp & closure": ["Opened and closed to confirm it holds through everyday wear.", "lock"],
    "Skin contact": ["Base metal checked against the listing's skin-safety claim.", "health_and_safety"]
  };
  /* FC Promise line — named from the SKU's first two checks ("Plating & clasp checked"), 2026-10-12.
     Names what is checked, never a result. */
  const J_SHORT = {
    "Plating coverage": "plating",
    "Stones & settings": "stones",
    "Clasp & closure": "clasp",
    "Skin contact": "skin"
  };
  const promiseLine = fc => {
    const n = fc.slice(0, 2).map(c => J_SHORT[c.title] || c.title.toLowerCase());
    const s = n.join(" & ") + " checked";
    return s.charAt(0).toUpperCase() + s.slice(1);
  };
  const jchecks = names => names.map(t => ({
    title: t,
    description: (JCHECKS[t] || [])[0],
    icon: (JCHECKS[t] || [])[1] || "verified"
  }));
  /* Care step descriptions — class-level guidance keyed by step title (caring.svg, 2026-10-12). */
